"use client";

import { useEffect } from "react";

export default function AdminError({ error, reset }: { error: Error & { digest?: string }; reset: () => void }) {
  useEffect(() => console.error(error), [error]);
  return (
    <div className="animate-fade-up rounded-lg border border-danger/30 bg-white p-8">
      <h1 className="font-display text-2xl font-semibold">This admin page failed to load</h1>
      <p className="mt-2 text-sm text-muted">{error.digest ? `Error reference ${error.digest}. ` : ""}Check the server logs for details.</p>
      <button onClick={reset} className="btn-dark press mt-4">Retry</button>
    </div>
  );
}
